// src/lib/mcp/tools/list-dispensary-menus.ts
var list_dispensary_menus_default = defineTool({
  name: "list_dispensary_menus",
  title: "List dispensary menus",
  description: "List the partner dispensaries whose menus are available on Cuddles AI.",
  inputSchema: {},
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: () => {
    const summary = DISPENSARY_MENUS.map((m) => ({
      id: m.id,
      label: m.label,
      currency: m.currency,
      contact: m.contact ?? null,
      item_count: m.items.length
    }));
    return {
      content: [{ type: "text", text: JSON.stringify(summary, null, 2) }],
      structuredContent: { dispensaries: summary }
    };
  }
});

// src/lib/mcp/tools/get-dispensary-menu.ts
import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.20.0";
import { z } from "npm:zod@^4.4.3";
var get_dispensary_menu_default = defineTool2({
  name: "get_dispensary_menu",
  title: "Get dispensary menu",
  description: "Get the full product menu (items, prices, categories) for a partner dispensary by id or name alias (e.g. 'tripple444', 'lef labs', 'dirty vapes').",
  inputSchema: {
    dispensary: z.string().min(1).describe("Dispensary id or a name alias, e.g. 'tripple444', 'lef labs'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ dispensary }) => {
    const q = dispensary.toLowerCase().trim();
    const match = DISPENSARY_MENUS.find(
      (m) => m.id === q || m.aliases.some((a) => a === q || q.includes(a) || a.includes(q))
    );
    if (!match) {
      return {
        content: [
          {
            type: "text",
            text: `No dispensary matched "${dispensary}". Use list_dispensary_menus to see available options.`
          }
        ],
        isError: true
      };
    }
    return {
      content: [{ type: "text", text: JSON.stringify(match, null, 2) }],
      structuredContent: { menu: match }
    };
  }
});

// src/lib/mcp/tools/search-strains.ts
import { defineTool as defineTool3 } from "npm:@lovable.dev/mcp-js@0.20.0";
import { z as z2 } from "npm:zod@^4.4.3";
import { createClient } from "npm:@supabase/supabase-js@^2.108.2";
function supabase() {
  const env = globalThis.process?.env ?? {};
  const url = env.SUPABASE_URL;
  const key = env.SUPABASE_PUBLISHABLE_KEY ?? env.SUPABASE_ANON_KEY;
  if (!url || !key) throw new Error("Supabase env not configured");
  return createClient(url, key, { auth: { persistSession: false, autoRefreshToken: false } });
}
var search_strains_default = defineTool3({
  name: "search_strains",
  title: "Search cannabis strains",
  description: "Search the Cuddles AI public strain catalog. Filter by category (e.g. sleep, energy, creativity, stress, pain, social) or free-text query on strain name.",
  inputSchema: {
    query: z2.string().optional().describe("Optional strain name substring."),
    category: z2.string().optional().describe("Optional effect category: sleep, energy, creativity, stress, pain, social."),
    limit: z2.number().int().min(1).max(50).optional().describe("Max rows (default 10).")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: true },
  handler: async ({ query, category, limit }) => {
    const sb = supabase();
    let q = sb.from("tenant_strains").select("strain_name, strain_type, category, primary_terpene, secondary_terpene, primary_effect, notes, thc_min, thc_max, in_stock").eq("in_stock", true).limit(limit ?? 10);
    if (category) q = q.ilike("category", `%${category}%`);
    if (query) q = q.ilike("strain_name", `%${query}%`);
    const { data, error } = await q;
    if (error) {
      return { content: [{ type: "text", text: error.message }], isError: true };
    }
    return {
      content: [{ type: "text", text: JSON.stringify(data ?? [], null, 2) }],
      structuredContent: { strains: data ?? [] }
    };
  }
});

